const deals = ($('Get Deals from HubSpot').first().json.results || []).map(d => d.properties);
const rows = $('Get Outbound Log').all().map(r => r.json).filter(r => r.email);
const DAY = 24*60*60*1000, now = Date.now();
// HubSpot default pipeline stage ids. Rename if your pipeline uses custom stages.
const stageNames = { appointmentscheduled: 'Meeting booked', qualifiedtobuy: 'Qualified', presentationscheduled: 'Site visit / demo',
  decisionmakerboughtin: 'Decision maker in', contractsent: 'Offer sent', closedwon: 'Won', closedlost: 'Lost' };
const byStage = {};
for (const d of deals) {
  const s = stageNames[d.dealstage] || d.dealstage;
  byStage[s] = byStage[s] || { count: 0, value: 0 };
  byStage[s].count++; byStage[s].value += Number(d.amount) || 0;
}
const won = deals.filter(d => d.dealstage === 'closedwon');
const lost = deals.filter(d => d.dealstage === 'closedlost');
const open = deals.filter(d => !['closedwon','closedlost'].includes(d.dealstage));
const stalled = open.filter(d => now - new Date(d.hs_lastmodifieddate).getTime() > 14*DAY)
  .map(d => ({ name: d.dealname, stage: stageNames[d.dealstage] || d.dealstage, amount: Number(d.amount) || 0 }));
const pct = (a, b) => b ? Math.round(a / b * 1000) / 10 : 0;
const variants = {};
for (const r of rows.filter(r => r.status === 'contacted' || r.replied === 'yes')) {
  const v = r.variant || 'none';
  variants[v] = variants[v] || { sent: 0, replies: 0 };
  variants[v].sent++; if (r.replied === 'yes') variants[v].replies++;
}
for (const v of Object.values(variants)) v.reply_rate = pct(v.replies, v.sent);
return [{ json: {
  period: 'Deals created in the last 90 days',
  total_deals: deals.length, open_deals: open.length,
  open_pipeline_value: open.reduce((s, d) => s + (Number(d.amount) || 0), 0),
  won_deals: won.length, won_value: won.reduce((s, d) => s + (Number(d.amount) || 0), 0),
  win_rate_pct: pct(won.length, won.length + lost.length),
  by_stage: byStage, stalled_deals: stalled, outbound_by_variant: variants,
} }];

// Claude returns text in content[0].text; pull out the JSON object
const claudeJson = r => { const t = (r.content && r.content[0] && r.content[0].text) || ''; return JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)); };
const m = $('Calculate Pipeline Metrics').first().json;
let ai = {};
try { ai = claudeJson($input.first().json); } catch (e) { ai = { headline: 'Weekly pipeline report', insights: [], actions: [] }; }
const money = n => Number(n || 0).toLocaleString('en-US');
const li = arr => (arr || []).map(x => `<li>${x}</li>`).join('');
const stageRows = Object.entries(m.by_stage).map(([s, v]) => `<tr><td>${s}</td><td>${v.count}</td><td>${money(v.value)}</td></tr>`).join('');
const varRows = Object.entries(m.outbound_by_variant).map(([k, v]) => `<tr><td>${k}</td><td>${v.sent}</td><td>${v.replies}</td><td>${v.reply_rate}%</td></tr>`).join('');
const stalled = m.stalled_deals.map(d => `<li>${d.name} (${d.stage}, ${money(d.amount)})</li>`).join('') || '<li>None</li>';
const t = 'style="border-collapse:collapse" cellpadding="6" border="1"';
const html = `<h2>${ai.headline}</h2>
<p><b>Open pipeline:</b> ${money(m.open_pipeline_value)} across ${m.open_deals} deals &nbsp;|&nbsp; <b>Won:</b> ${m.won_deals} (${money(m.won_value)}) &nbsp;|&nbsp; <b>Win rate:</b> ${m.win_rate_pct}%</p>
<h3>Insights</h3><ul>${li(ai.insights)}</ul>
<h3>Actions this week</h3><ol>${li(ai.actions)}</ol>
<h3>Pipeline by stage</h3><table ${t}><tr><th>Stage</th><th>Deals</th><th>Value</th></tr>${stageRows}</table>
<h3>Outbound A/B test</h3><table ${t}><tr><th>Variant</th><th>Sent</th><th>Replies</th><th>Reply rate</th></tr>${varRows}</table>
<h3>Stalled deals (no update in 14+ days)</h3><ul>${stalled}</ul>
<p style="color:#888">${m.period}. Generated automatically.</p>`;
return [{ json: { subject: 'Weekly pipeline: ' + ai.headline, html } }];
